const items = $input.all();
const results = [];

for (const item of items) {

  const input = item.json;

  // ============================================================
  // 1. Get Anthropic response
  // ============================================================

  const rawText = input.content?.[0]?.text;

  // ============================================================
  // 2. Check response
  // ============================================================

  if (typeof rawText !== 'string' || !rawText.trim()) {

    results.push({
      json: {
        valid: false,
        validation_status: 'FAILED',
        total_records: 0,
        errors: [
          'No usable Anthropic response was found.'
        ]
      }
    });

    continue;
  }

  // ============================================================
  // 3. Parse JSON
  // ============================================================

  let data;

  try {

    data = JSON.parse(rawText.trim());

  } catch (error) {

    results.push({
      json: {
        valid: false,
        validation_status: 'FAILED',
        total_records: 0,
        errors: [
          'Anthropic response is not valid JSON.',
          error.message
        ],
        raw_response: rawText
      }
    });

    continue;
  }

  // ============================================================
  // 4. Validate root structure
  // ============================================================

  const errors = [];

  if (
    typeof data !== 'object' ||
    data === null ||
    Array.isArray(data)
  ) {

    errors.push(
      'AI response must be a JSON object.'
    );

  }

  // ============================================================
  // 5. Validate atendimentos
  // ============================================================

  if (!Array.isArray(data.atendimentos)) {

    errors.push(
      'The "atendimentos" field must be an array.'
    );

  }

  // ============================================================
  // 6. Validate records
  // ============================================================

  const requiredFields = [
    'cnes',
    'placa',
    'tipologia',
    'compet',
    'uf',
    'municipio',
    'oci',
    'quantidade'
  ];

  if (Array.isArray(data.atendimentos)) {

    if (data.atendimentos.length === 0) {

      errors.push(
        'No attendance records were found.'
      );

    }

    data.atendimentos.forEach((record, index) => {

      // --------------------------------------------------------
      // Record must be an object
      // --------------------------------------------------------

      if (
        typeof record !== 'object' ||
        record === null ||
        Array.isArray(record)
      ) {

        errors.push(
          `Attendance ${index} must be a JSON object.`
        );

        return;
      }

      // --------------------------------------------------------
      // Required fields
      // --------------------------------------------------------

      for (const field of requiredFields) {

        if (
          !Object.prototype.hasOwnProperty.call(
            record,
            field
          )
        ) {

          errors.push(
            `Missing field: atendimentos[${index}].${field}`
          );

        }

      }

      // --------------------------------------------------------
      // Empty strings
      // null is allowed
      // --------------------------------------------------------

      for (const field of requiredFields) {

        const value = record[field];

        if (value === '') {

          errors.push(
            `Empty field: atendimentos[${index}].${field}`
          );

        }

      }

      // --------------------------------------------------------
      // Validate quantity
      // --------------------------------------------------------

      const quantidade = record.quantidade;

      if (
        quantidade !== null &&
        quantidade !== undefined
      ) {

        if (
          typeof quantidade !== 'number' ||
          !Number.isFinite(quantidade) ||
          !Number.isInteger(quantidade) ||
          quantidade < 0
        ) {

          errors.push(
            `Invalid quantity at atendimentos[${index}]: ${quantidade}`
          );

        }

      }

      // --------------------------------------------------------
      // Check unexpected fields
      // --------------------------------------------------------

      for (const field of Object.keys(record)) {

        if (!requiredFields.includes(field)) {

          errors.push(
            `Unexpected field: atendimentos[${index}].${field}`
          );

        }

      }

    });

  }

  // ============================================================
  // 7. Final result
  // ============================================================

  results.push({
    json: {

      valid: errors.length === 0,

      validation_status:
        errors.length === 0
          ? 'PASSED'
          : 'FAILED',

      total_records:
        Array.isArray(data.atendimentos)
          ? data.atendimentos.length
          : 0,

      errors,

      data

    }
  });

}

return results;

const input = $input.first().json;

// ============================================================
// Get validated attendance data
// Obtém os dados de atendimento validados
// ============================================================

const atendimentos = input.data?.atendimentos || [];

const results = [];

// ============================================================
// Create one n8n item per attendance
// Cria um item do n8n para cada atendimento
// ============================================================

atendimentos.forEach((record, index) => {

  results.push({
    json: {

      // ========================================================
      // Extracted fields
      // Campos extraídos pela IA
      // ========================================================

      cnes:
        record.cnes ?? null,

      placa:
        record.placa ?? null,

      tipologia:
        record.tipologia ?? null,

      compet:
        record.compet ?? null,

      uf:
        record.uf ?? null,

      municipio:
        record.municipio ?? null,

      oci:
        record.oci ?? null,

      qtd:
        record.quantidade ?? null,

      // ========================================================
      // Technical pipeline fields
      // Campos técnicos do pipeline
      // ========================================================

      atendimento:
        `ATD-${String(index + 1).padStart(4, '0')}`,

      id_relatorio:
        'YOUR_GOOGLE_DRIVE_FILE_ID',

      file_name:
        'sample_report.pdf',

      data_processamento:
        new Date().toISOString(),

      valid:
        input.valid === true

    }
  });

});

return results;

// Build validation error report
// Cria o relatório de erro da validação

const input = $input.first().json;

// ============================================================
// Get original document information
// Obtém informações do documento original
// ============================================================

const source = $('INGEST — PDF Document').first().json;

return [
  {
    json: {

      // ========================================================
      // Validation status
      // Status da validação
      // ========================================================

      status: 'FAILED',

      validation_status:
        input.validation_status || 'FAILED',

      // ========================================================
      // Document information
      // Informações do documento
      // ========================================================

      file_id:
        source.id || null,

      file_name:
        source.name || null,

      // ========================================================
      // Validation information
      // Informações da validação
      // ========================================================

      total_records:
        input.total_records ?? 0,

      errors:
        Array.isArray(input.errors)
          ? input.errors
          : [
              'Unknown validation error / ' +
              'Erro de validação desconhecido'
            ],

      // ========================================================
      // Processing timestamp
      // Data e hora do processamento
      // ========================================================

      timestamp:
        new Date().toISOString()
    }
  }
];

const fileId = 'YOUR_GOOGLE_DRIVE_FILE_ID';

const items = $input.all();

const exists = items.some(item => {
  return item.json?.id_relatorio === fileId;
});

return [
  {
    json: {
      id_relatorio: fileId,
      duplicate: exists,
      dedup_status: exists ? 'DUPLICATE' : 'NEW'
    }
  }
];
